insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('ometepe-island-nicaragua', '10S', 'Ometepe Island, Nicaragua', 'Nicaragua', 'Ometepe Island', 'live', 'verified', 'mountainValley', 'Nicaragua', '{"wellness"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":null,"safety":{"emergency":"118","emergency_fire":"128","book_enabled":false,"bin":"NO SAFE ZONE (content-only)","content_only":true,"redirect_eligible":true,"founder_review_flag":"Political wrongful-detention risk may not register with typical leisure travelers; requires deliberate founder + compliance-attorney review before any Book path — do not soft-open on demand alone","remote_flag":true,"trauma_note":"No trauma care on-island; comprehensive care only in Managua; serious cases → Managua → US medical evacuation; long transfer times from lake island"},"timing":{"peak":"Dry season Dec–Apr (clear skies, passable hiking trails; March standout)","inflection":"Peak volume December; late-Nov/early-Dec good weather pre-rush; Nov–Feb choppy lake winds","off_season":"May–Nov green/wet — muddy trails, clouded summits","fire_date":"held — pending advisory clearance + founder/attorney"},"jewels":[{"name":"Volcán Concepción summit (1,610 m)","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Nicaragua''s second-highest volcano and one of the most perfectly formed cones in the Americas; a serious dawn climb. price","si":"expedition","blurb":"Nicaragua''s second-highest volcano and one of the most perfectly formed cones in the Americas; a serious dawn climb. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Volcán Maderas summit + crater lagoon (1,394 m)","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","si":"expedition","blurb":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Río Istián kayak","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/istian/index.php","hook":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","si":"expedition","blurb":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","commission":"dormant"},{"name":"San Ramón waterfall (64 m)","si_tag":"expedition","tier":"essential","source":"https://www.theselvistaexperience.com/hiking-san-ramon-waterfall","hook":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","si":"expedition","blurb":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","commission":"dormant"},{"name":"Punta Jesús María sandbar","si_tag":"expedition","tier":"essential","source":"https://ometepenicaragua.com/charcoverde/index.php","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","si":"expedition","blurb":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Ojo de Agua natural spring","si_tag":"wellness","tier":"essential","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","si":"wellness","blurb":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Charco Verde Nature Reserve","si_tag":"wellness","tier":"essential","source":"https://travelmademedoit.com/charco-verde-ometepe/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","si":"wellness","blurb":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Pre-Columbian petroglyphs (1,700+)","si_tag":"Culture/Romance","tier":"essential","source":"https://www.dreambigtravelfarblog.com/blog/ometepe-nicaragua","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","si":"Culture/Romance","blurb":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","when":"Dry season Dec–Apr","commission":"dormant"}],"faq":[{"q":"What makes Ometepe Island special?","a":"Ometepe is the largest island in a freshwater lake in the world and a UNESCO Biosphere Reserve since 2010, formed by two volcanoes — active Concepción (1,610 m) and dormant Maderas (1,394 m) — joined by the Isthmus of Istián across roughly 276 km². It also holds over 1,700 pre-Columbian petroglyphs across more than 100 documented sites.","source":"en.unesco.org; lacgeo.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"How hard are the Ometepe volcano hikes?","a":"Both are serious. Concepción is a strenuous ~10-hour dawn-start climb; Maderas is ~8 hours via a ~4.5 km trail from Balgüe / Finca Magdalena, with a crater lagoon you can swim in at the summit. A licensed local guide is mandatory for both because the upper slopes are exposed, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com; alongdustyroads.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where can you swim on Ometepe?","a":"Ojo de Agua (\"eye of the water\") is the island''s signature spot — a natural mineral swimming hole fed by an underground river originating on Volcán Maderas, about 2 km from Santo Domingo. Go early or late to avoid crowds. Maderas'' summit crater lagoon and designated lake beaches are the other locally advised swims.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"wellness"},{"q":"Where do couples stay on Ometepe?","a":"Ometepe skews to off-grid eco-lodges rather than resorts. Totoco Eco-Lodge (8 design cabins on Maderas'' slopes, lake-and-Concepción views, farm-to-table dining), Finca del Sol (a 100% sustainable eco-lodge with permaculture farm), and Hacienda Mérida give the quiet, unscripted, two-people-and-a-volcano energy.","source":"steppestravel.com; hotelfincadelsol.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Two things: political detention and remoteness. Per the State Department, US nationals face serious risk of wrongful detention, exit bans, and detentions of weeks-plus, with some crimes carrying 50+ year sentences. And there is no trauma-grade care on-island — comprehensive care exists only in Managua, so a serious case realistically means Managua then a US medical evacuation.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is climbing an active volcano here dangerous?","a":"Concepción is an active stratovolcano (its last significant ash event was March 2010), and its summit hike is strenuous, exposed, and dawn-started; Maderas is dormant but steep, muddy, and cloud-forest-slick. A licensed guide is mandatory on both, and you should check volcanic status before going — though all of this fires as content only under the Level 3 advisory.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"jsonld_type":"TouristDestination","freshness":"2026-07-07","search_language":"es-NI","local_keywords":["Isla de Ometepe qué hacer","Volcán Concepción","Volcán Maderas laguna cráter","Ojo de Agua Ometepe","cascada San Ramón Ometepe","kayak Río Istián","petroglifos Ometepe","ferry San Jorge Ometepe"],"hreflang":["en","es-NI"],"primary_keyword":"Ometepe Island"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"wellness","status":"live"}],"ultra":[{"name":"Totoco Eco-Lodge","location":"Balgüe","price_tier":"mid/boutique-eco","commission_path":"dormant","source":"https://www.steppestravel.com/accommodation/totoco-eco-lodge/"},{"name":"Finca del Sol Eco Lodge","location":"Maderas base","price_tier":"mid/eco","commission_path":"dormant","source":"https://hotelfincadelsol.com/"},{"name":"Hacienda Mérida","location":"Mérida","price_tier":"value/mid","commission_path":"dormant","source":"https://www.hmerida.com/espanol/activity/1"}],"source_verified":null,"hero":{"query":"Ometepe Island, Nicaragua, Nicaragua"},"geo":{"lat":11.5,"lng":-85.5833}}'::jsonb, 73),
  ('osa-peninsula-corcovado-costa-rica', '10S', 'Osa Peninsula / Corcovado', 'Costa Rica', 'Corcovado rainforest at the continent''s edge', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","diveglobal"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Corcovado holds 2.5% of the world''s biodiversity in 41,800 hectares — ''the most biologically intense place on Earth'' (National Geographic)","Certified guide LEGALLY MANDATORY for all Corcovado entry (SINAC rule since Feb 1 2014)","Caño Island is Costa Rica''s #2 dive site (after Cocos), 30–100+ ft viz, capped at 120 visitors/day","Cocos Island = liveaboard-only pilgrimage, ~36-hr sail from Puntarenas, world''s most consistent schooling hammerheads","Golfo Dulce is one of only four tropical fjords on Earth and hosts BOTH hemispheres'' humpback populations"],"safety":{"emergency":"911","advisory_level":"L2","book_enabled":true,"air_access_verified":true,"air_access":"SJO → Drake Bay (DRK) / Puerto Jiménez (PJM) daily small-strip flights (~40–45 min); or 6–8 hr overland 4×4 drive","remote_flag":true,"medevac_note":"Deep-rural; nearest clinic Puerto Jiménez → San José for major care; Sirena has no road; Cocos ~36 hr by sea","hazards":["tide-timed river crossings (crocodile + bull shark at Rio Sirena/Rio Claro mouths)","jungle heat/humidity","Pacific rip currents","venomous snakes (fer-de-lance)","no-fly-after-diving (Caño + Cocos)"],"malaria":"low but present in region; Corcovado itself generally not a malaria concern — consult travel clinic","dengue":"primary mosquito risk; spikes May–Nov rainy season (CR 31,000+ cases 2024)","water":"potable in serviced areas; follow lodge guidance in deep-Osa","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-19","page_updated":"2026-05-19T11:42:25+01:00"}},"timing":{"terrestrial_peak":"mid-Dec–Apr (dry, Corcovado access best)","green_season":"May–Nov (lush, some lodge closures, access degrades)","whale_season":"Jul–Nov Southern humpback (prime late Aug–Sep) + Nov–Feb Northern humpback","cocos_hammerhead_peak":"Jun–Dec","curve_start":"early-mid December","fire_date":"late November (curve-start − 1–2 wks); secondary early-July for whale+hammerhead","booking_lead":"eco-lodges 3–6 mo; Sirena permits 3–4 mo; Cocos liveaboard 6–18 mo","sharpen_note":"sharpen on live tracking — windows drift year to year"},"jewels":[{"name":"Sirena Ranger Station, Corcovado","si_tag":"expedition","highlight":"tapir ~70% overnight, all 4 monkey species, scarlet macaw near-guaranteed, peccary herds 30+","tier":"premier","source":"https://vamosrentacar.com/blog/corcovado-national-park-sirena-station/","si":"expedition","commission":"guided trek + Sirena overnight via DMC; margin on guide service"},{"name":"Caño Island Biological Reserve","si_tag":"diveglobal","highlight":"CR #2 dive site, 30–100+ ft viz, sharks/rays/turtles, 120-pax/day cap","tier":"premier","source":"https://www.entercostarica.com/attractions/national-parks-and-refuges/cano-island","si":"diveglobal","commission":"day-dive/snorkel net-rate/referral"},{"name":"Cocos Island National Park (UNESCO)","si_tag":"diveglobal","highlight":"world''s most consistent schooling hammerheads; liveaboard-only, 36-hr sail from Puntarenas","tier":"ultra","source":"https://www.aggressor.com/destination/Cocos","si":"diveglobal","commission":"own CLIA/DLA lane (Aggressor/Undersea Hunter)"},{"name":"Golfo Dulce (tropical fjord)","si_tag":"WILDLIFE_NATURE/RHN","highlight":"one of 4 tropical fjords on Earth; both hemispheres'' humpbacks; dolphins, mangroves","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"WILDLIFE_NATURE/RHN","commission":"lodge-bundled boat tour"},{"name":"Drake Bay","si_tag":"DIVE/GEA","highlight":"northern-Osa gateway to Caño Island + Corcovado San Pedrillo; sportfishing, night tours","tier":"comfort","source":"https://www.copadearbol.com/osa-peninsula-eco-lodge/","si":"DIVE/GEA","commission":"lodge + activity referral"},{"name":"Puerto Jiménez","si_tag":"expedition","highlight":"frontier town + PJM airstrip; Golfo Dulce + southern Corcovado gateway","tier":"comfort","source":"https://mytanfeet.com/driving-in-costa-rica/puerto-jimenez-osa-peninsula/","si":"expedition","commission":"gateway nights + transfers"},{"name":"Matapalo surf & waterfalls","si_tag":"expedition","highlight":"secluded breaks + jungle cascades at peninsula tip","tier":"comfort","source":"https://www.crsurfzone.com/corcovado-national-park.html","si":"expedition","commission":"lodge-bundled excursion"},{"name":"Whale-watching, Golfo Dulce","si_tag":"WILDLIFE_NATURE","highlight":"both hemispheres'' humpbacks (Jul–Nov Southern + Nov–Feb Northern)","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"wildlife","commission":"guided boat referral"},{"name":"Cacao finca / farm-to-bar chocolate","si_tag":"expedition","highlight":"Indigenous + smallholder cacao experience","tier":"comfort","source":"https://www.osawild.travel/locations/","si":"expedition","commission":"referral"}],"faq":[{"q":"Do you need a guide to hike Corcovado National Park?","a":"Yes — a certified guide is legally mandatory for all Corcovado entry, a SINAC rule in force since February 1, 2014 and enforced at every ranger station, where unguided visitors are turned away. Build the guided-trek product; there is no compliant self-guided version to sell.","source":"Wikipedia — Corcovado National Park, 2026-07-06","si_tag":"expedition"},{"q":"Can you dive Cocos Island on a day trip?","a":"No. Cocos is liveaboard-only — it lies ~342 mi off the Pacific coast, an ~36-hr open-ocean crossing from Puntarenas, and is sold as 8/10/12-night charters (15/21/27 dives) via Aggressor or Undersea Hunter. Berths book 6–18 months out, so plan far ahead.","source":"aggressor.com, 2026-07-06","si_tag":"diveglobal"},{"q":"Are the Osa eco-lodges right for a honeymoon?","a":"Yes — the Osa is honeymoon-grade seclusion without the resort cliché: private-reserve bungalows over the Pacific, canopy suites and no Wi-Fi. Lapa Rios alone offers 16 ocean-view bungalows across 1,000 protected acres, and remote lodges bundle meals, guided excursions and transfers by necessity.","source":"laparios.com, 2026-07-06","si_tag":"romance"},{"q":"When can you see whales in Golfo Dulce?","a":"Golfo Dulce — one of only four tropical fjords on Earth — draws both hemispheres'' humpbacks, so the season is unusually long: Southern-hemisphere humpbacks calve July–November (prime late Aug–Sept), and Northern-hemisphere humpbacks arrive November–February.","source":"nicuesalodge.com, 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for on a Corcovado trek?","a":"The tide-timed river crossings. Rio Sirena and Rio Claro are the most dangerous, with American crocodiles and bull sharks patrolling the river mouths, so guides cross only at low tide and never in storms. This — plus jungle heat and deep-remote medevac — is the true gatekeeper, above petty crime.","source":"crsurfzone.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving Cocos Island dangerous?","a":"It is advanced diving in a strong-current, deeply remote environment. DAN membership and dive insurance are essential, no-fly-after-diving surface intervals apply, and because the site is ~36 hr from land the vessel itself is the only evacuation. Not a first-timer''s trip.","source":"aggressor.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Osa Peninsula & Corcovado, Costa Rica — The Most Biologically Intense Place on Earth | TravelWell.World","search_language":"es-CR","local_keywords":["Parque Nacional Corcovado","Península de Osa","Isla del Coco buceo","Bahía Drake","Golfo Dulce ballenas","Puerto Jiménez"],"long_tail_en":["Corcovado guided tour","Sirena station Corcovado","Caño Island diving Drake Bay","Cocos Island liveaboard hammerhead","Osa Peninsula luxury eco lodge","Golfo Dulce whale watching"],"hreflang":["en","es-CR"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"name":"Lapa Rios","operator":"Böëna / Cayuga Collection","location":"above Corcovado","earn":"Virtuoso/consortia; AoR via ST Costa Rica DMC","tier":"ultra"},{"name":"El Remanso","location":"Puerto Jiménez / private beach","earn":"Virtuoso/consortia + full-property buyout","tier":"ultra"},{"name":"Copa de Árbol","location":"Drake Bay","earn":"consortia","tier":"ultra"},{"name":"Playa Cativo","location":"Golfo Dulce","earn":"consortia + private-reserve buyout","tier":"ultra"},{"name":"Aguila de Osa","location":"Drake Bay","earn":"consortia + Caño Island dive referral","tier":"ULTRA/PREMIUM"},{"name":"Cocos private liveaboard charter","operator":"Aggressor / Undersea Hunter","earn":"own CLIA/DLA lane — AoR/MoR via DLA relationship","tier":"ultra"},{"name":"Kasiiya Papagayo","correction":"in GUANACASTE, not Osa — do not sell as Osa property","tier":"N/A"}],"source_verified":"2026-07-06","hero":{"query":"Osa Peninsula / Corcovado, Costa Rica"},"geo":{"lat":8.54,"lng":-83.59}}'::jsonb, 74),
  ('ouro-preto-tiradentes-brazil', '10S', 'Ouro Preto, Tiradentes & Colonial Minas, Brazil', 'Brazil', 'Gold-rush baroque in the mountains', 'live', 'verified', 'venice', 'Rio & The Southeast Coast', '{"romance","culture","culinary"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_medical":"192","advisory_level":"L2","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/brazil-travel-advisory.html","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":{"international":"CNF (Belo Horizonte / Confins — Tancredo Neves Intl)","gateway_transfer":"~87 mi / ~2 hrs by road to Ouro Preto"},"water":"bottled recommended (tap not advised for visitors)","caveats":["Steep, uneven, car-free cobblestone at altitude — #1 injury risk; sturdy shoes; flag limited mobility","Mountain-road transfers between towns; avoid night driving; driver-guide/DMC preferred","Mina da Passagem = guided underground descent only (trolley to 120 m)","Standard L2 urban caution + favela avoidance in Belo Horizonte gateway (favelas = L4 Do Not Travel)","Trauma → Belo Horizonte private hospitals (~1.5–2 hrs) → US medical evacuation; confirm evac coverage","Dengue precautions (repellent; worse in warm/wet off-season Oct–Mar)"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel Amazonas State FCDO advises against all but essential travel to the following river areas towards the west of Amazonas State: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State Find out more about why FCDO advises against travel ."},{"form":"against all but essential travel","text":"advises against all but essential travel: along the Amazonas (Amazon) River and its tributaries west of the town of Codajás and east of the town of Belém do Solimões in Amazonas State along any part of the Itaquaí River in Amazonas State along any part of the Japurá River or its tributaries in Amazonas State along the Rio Negro (Black River) and its tributaries north or west of the town of Barcelos in Amazonas State There are risks to travellers in river areas towards the west of Amazonas State, where Brazil shares borders with Colombia, Peru and Venezuela, due to criminal activity."}],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-19","page_updated":"2026-05-11T12:32:48+01:00"}},"timing":{"peak":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","cultural_spikes":[{"event":"Ouro Preto Semana Santa (Holy Week processions + sawdust carpets)","dates":"2026-03-29 to 2026-04-04","easter":"2026-04-05","note":"eight processions; marquee event; rooms lock months out"},{"event":"Tiradentes Festival de Cultura e Gastronomia (28th ed.)","dates":"2026-08-21 to 2026-08-30","note":"Condé Nast-recognized; books hard"}],"winter_core":"Jun–Jul (coolest, driest, quietest — inside the dry peak; fireplace-pousada romance)","inflection":"~6–8 weeks before each spike (early Feb for Semana Santa; late Jun/early Jul for Tiradentes festival)","fire_date":"curve-start − 1–2 weeks → mid-January (Semana Santa) and mid-June (Tiradentes festival)","off_season":"Oct–Mar (warmer/wetter, lush gardens, softer prices — value + fill lane)"},"jewels":[{"name":"São Francisco de Assis (Ouro Preto)","si_tag":"culture","tier":"essential","source":"https://whc.unesco.org/en/list/124","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"widely regarded as Aleijadinho''s masterpiece; richly carved facade + interior with Athayde ceiling. The single most important baroque church in Brazil","si":"culture","blurb":"widely regarded as Aleijadinho''s masterpiece; richly carved facade + interior with Athayde ceiling. The single most important baroque church in Brazil","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC/guide; church entry non-commissionable"},{"name":"Nossa Senhora do Pilar (Ouro Preto)","si_tag":"culture","tier":"essential","source":"https://en.wikipedia.org/wiki/Ouro_Preto","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"one of the richest church interiors in Minas, lavishly gilded; \"Basílica Menor.\"","si":"culture","blurb":"one of the richest church interiors in Minas, lavishly gilded; \"Basílica Menor.\"","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC/guide; entry non-commissionable"},{"name":"Congonhas — Twelve Prophets (Bom Jesus do Matosinhos)","si_tag":"culture","tier":"comfort","source":"https://whc.unesco.org/en/list/334/","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"twelve soapstone prophets on the sanctuary stairway + seven Passion chapels; UNESCO-inscribed 1985, a crowning achievement of baroque art","si":"culture","blurb":"twelve soapstone prophets on the sanctuary stairway + seven Passion chapels; UNESCO-inscribed 1985, a crowning achievement of baroque art","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC day-trip; sanctuary entry non-commissionable"},{"name":"Ouro Preto Semana Santa processions","si_tag":"culture","tier":"premier","source":"https://www.catholicsandcultures.org/brazil/holy-week-ouro-preto","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"eight processions across Holy Week over colored-sawdust street carpets. The marquee cultural event","si":"culture","blurb":"eight processions across Holy Week over colored-sawdust street carpets. The marquee cultural event","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC festival package carries margin; processions free/public"},{"name":"Mariana + Mina da Passagem gold mine","si_tag":"culture","tier":"comfort","source":"https://www.tripadvisor.com/Attraction_Review-g303386-d2389589-Reviews-Minas_da_Passagem-Mariana_State_of_Minas_Gerais.html","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Minas''s first capital + the largest gold mine open to the public on Earth","si":"culture","blurb":"Minas''s first capital + the largest gold mine open to the public on Earth","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC/tour affiliate for guided descent + Mariana half-day"},{"name":"Inhotim (open-air art + botanical, Brumadinho)","si_tag":"culture","tier":"comfort","source":"https://en.wikipedia.org/wiki/Inhotim","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"DMC transfer + tour affiliate; entry non-commissionable"},{"name":"Tiradentes cobblestone jewel-box","si_tag":"romance","tier":"comfort","source":"https://www.footlooselemonjuice.com/tiradentes-minas-gerais-2/","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"car-light historic core, art galleries on the Rota dos Atêlieres, horse-drawn wagon rides, boutique pousadas; Minas''s most intimate romantic base","si":"romance","blurb":"car-light historic core, art galleries on the Rota dos Atêlieres, horse-drawn wagon rides, boutique pousadas; Minas''s most intimate romantic base","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"pousada/villa + DMC"},{"name":"Maria-Fumaça steam train (Tiradentes ↔ São João del-Rei)","si_tag":"romance","tier":"essential","source":"https://www.civitatis.com/en/ouro-preto/sao-joao-rei-tiradentes-maria-fumaca/","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"vintage steam locomotive, 12 km through 19th-century countryside, weekends only; a slow, romantic set-piece","si":"romance","blurb":"vintage steam locomotive, 12 km through 19th-century countryside, weekends only; a slow, romantic set-piece","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"tour affiliate / DMC; face-value fare non-commissionable"},{"name":"São João del-Rei baroque + railway heritage","si_tag":"romance","tier":"essential","source":"https://www.footlooselemonjuice.com/tiradentes-minas-gerais-2/","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Aleijadinho-attributed São Francisco de Assis church, the railway roundhouse & museum, Tancredo Neves Memorial, Solar dos Neves. A cultured half-day paired with Tiradentes","si":"romance","blurb":"Aleijadinho-attributed São Francisco de Assis church, the railway roundhouse & museum, Tancredo Neves Memorial, Solar dos Neves. A cultured half-day paired with Tiradentes","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"DMC half-day; museum/church entry non-commissionable"},{"name":"Fazenda-stay countryside + prospector trails","si_tag":"romance","tier":"comfort","source":"https://www.theultimatetravelcompany.co.uk/south-america/brazil/ouro-preto-minas-gerais","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"working/historic farm estates around Tiradentes and the Serra circuit; ride or walk trails once cut by gold prospectors, swim beneath waterfalls","si":"romance","blurb":"working/historic farm estates around Tiradentes and the Serra circuit; ride or walk trails once cut by gold prospectors, swim beneath waterfalls","when":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","commission":"villa/fazenda MoR + DMC"},{"name":"Mineiro comfort-food circuit (pão de queijo, feijão-tropeiro, tutu)","si_tag":"culinary","tier":"essential","source":"https://foodandroad.com/what-to-eat-in-minas-gerais-traditional-foods/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culinary","when":"year-round","commission":"DMC food-experience / tour affiliate; restaurants direct"},{"name":"Artisanal cachaça trail","si_tag":"culinary","tier":"essential","source":"https://foodandroad.com/what-to-eat-in-minas-gerais-traditional-foods/","timing":"Dry season Apr–Sep — best for cobblestone walking, mountain roads, mine tours, churches, hiking","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Minas is Brazil''s largest producer of artisanal cachaça; the tropeiros carried Paraty ca