pping)"},"jewels":[{"name":"Puerto Pirámides whale-watch (Southern right whales)","si_tag":"expedition","window":"Jun–mid-Dec, peak Sep–Oct","tier":"comfort","source":"https://www.puertopiramides.gov.ar/whales-season/","hook":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","si":"expedition","blurb":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","commission":"activity / DMC bundle"},{"name":"Punta Norte orca beaching-attack","si_tag":"expedition","window":"Mar–Apr (never guaranteed)","tier":"comfort","source":"https://peninsulavaldes.com/wildlife/orcas","hook":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","si":"expedition","blurb":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","commission":"DMC / specialist wildlife operator"},{"name":"Caleta Valdés elephant seals","si_tag":"expedition","window":"Aug–Nov combat; pupping Dec–Feb","tier":"comfort","source":"https://peninsulavaldes.com/wildlife/sea-elephant","si":"expedition","commission":"DMC circuit / activity"},{"name":"Punta Tombo Magellanic penguins","si_tag":"expedition","window":"Sep–Mar, chicks Oct–Nov","tier":"comfort","source":"https://www.interpatagonia.com/puertomadryn/penguins-punta-tombo.html","si":"expedition","commission":"DMC day-trip / activity"},{"name":"Puerto Madryn sea-lion dive (Punta Loma)","si_tag":"Dive/OCA","window":"year-round; best Sep–Oct water","tier":"comfort","source":"https://www.civitatis.com/en/puerto-madryn/sea-lion-dive/","hook":"Dive among wild sea lions — a top-handful global experience","si":"Dive/OCA","blurb":"Dive among wild sea lions — a top-handful global experience","commission":"dive-operator activity"},{"name":"Golfo Nuevo wreck cluster (Folias/Miralles/Albatros)","si_tag":"Dive/OCA","window":"year-round (cold, no-fly)","tier":"comfort","source":"https://travel.padi.com/dive-trip/puerto-madryn/sea-lions-dive-ship-wreck-12594/","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Sunken cargo ships as artificial reef — octopus, sea stars, fish schools; cold-water, no-fly","si":"Dive/OCA","blurb":"Sunken cargo ships as artificial reef — octopus, sea stars, fish schools; cold-water, no-fly","when":"whale season Sep–Oct","commission":"dive-operator activity"},{"name":"Isla de los Pájaros birding","si_tag":"Wildlife & Nature (future)","window":"year-round","tier":"essential","source":"https://peninsulavaldes.com/travel-guide/gaiman/gaiman-the-welsh-colony-the-ultimate-guide","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Protected bird island viewed from a shoreline hide — herons, cormorants, migratory shorebirds","si":"Wildlife & Nature (future)","blurb":"Protected bird island viewed from a shoreline hide — herons, cormorants, migratory shorebirds","when":"whale season Sep–Oct","commission":"DMC circuit add-on"},{"name":"Kayak with sea lions","si_tag":"Wildlife & Nature (future)","window":"spring–summer","tier":"comfort","source":"https://www.civitatis.com/en/puerto-madryn/sea-lion-dive/","si":"Wildlife & Nature (future)","commission":"activity"},{"name":"Gaiman Welsh-Patagonian afternoon tea","si_tag":"culture add-on","window":"year-round","tier":"essential","source":"https://www.interpatagonia.com/gaiman/welsh-tea-gaiman.html","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Casa de té tradition in a living Welsh colony; pairs naturally with a Punta Tombo day","si":"culture add-on","blurb":"Casa de té tradition in a living Welsh colony; pairs naturally with a Punta Tombo day","when":"whale season Sep–Oct","commission":"DMC day-trip inclusion"}],"faq":null,"seo":{"meta_title":"Península Valdés & Puerto Madryn Argentina — Whales, Orcas & Penguins | TravelWell","search_language":"es-AR","local_keywords":["Península Valdés ballenas","avistaje de ballenas Puerto Madryn","orcas Punta Norte","Punta Tombo pingüinos","elefantes marinos Caleta Valdés","buceo con lobos marinos Puerto Madryn","té galés Gaiman"],"hreflang":["en","es-AR"],"jsonld_type":"TouristDestination","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Estancia Rincón Chico","tier":"ultra","why":"20km private peninsula coastline, 8 rooms, no outside visitors, NatGeo Traveller top-10 LatAm lodge","earning":"MoR / consortia-preferred FIT","mor_rung":true,"source":"https://rinconchico.com.ar/"},{"name":"Hotel Territorio","tier":"premium design 4★","why":"concrete-and-wood boutique, 36–38 rooms facing Golfo Nuevo, best-in-town whale-season base","earning":"MoR / bedbank / consortia","mor_rung":true,"source":"https://www.greatsmallhotels.com/puerto-madryn-boutique-hotels/hotel-territorio"},{"name":"Faro Punta Delgada","tier":"premium character / upper-mid","why":"100-year working lighthouse-estancia, 27 rooms, remote southern tip, elephant seals below cliff","earning":"MoR / DMC net","mor_rung":true,"source":"https://www.swoop-patagonia.com/argentina/peninsula-valdes/hotels/faro-punta-delgada"}],"source_verified":null,"hero":{"query":"Península Valdés & Puerto Madryn, Argentina, Argentina"},"geo":{"lat":-42.5,"lng":-64}}'::jsonb, 79)
