  ('placencia-belize', '10S', 'Placencia', 'Belize', 'Whale sharks and mainland sand', 'live', 'verified', 'oceanAerial', 'Belize', '{"liveaboard","expedition","diveglobal","ocean","wildlife","culture"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Placencia is Belize''s southern beach peninsula with the country''s best mainland beaches and its main resort/romance-wedding coast.","Gladden Spit, off Placencia, is the world''s most predictable whale-shark aggregation, timed to the Mar-Jun full moons (peak Apr-May).","The southern barrier reef (Silk Cayes, Laughing Bird Caye NP, South Water Caye) launches from Placencia; the outer atolls are reachable.","Monkey River (howler monkeys, manatees) and the Cockscomb Basin (world''s first jaguar preserve) are easy day trips.","Access is BZE -> PLJ (Placencia airstrip) by 20-30 min puddle-jumper on Tropic Air / Maya Island Air; ~3.5-4 hr drive alternative."],"safety":{"emergency":"911 (Belize national; verify on arrival)","hyperbaric_chamber":"Nearest chambers on Ambergris Caye (San Pedro): SSS Network 24/7 226-2851; Belize Chamber Project 24/7 226-2660 — DISTANCE FLAG from southern reef, plan conservative profiles","hospital":"No peninsula trauma center; Placencia/Dangriga clinics stabilize; serious trauma evacuates to Belize City","book_enabled":true,"l3_disclosure":true,"advisory_reissued":"2026-06-18","advisory_codes":"C (Crime) only","state_dept_carveout":"only Southside Belize City restricted; Placencia open","stay_in_zone":true,"air_access_verified":"BZE -> PLJ (Placencia) by puddle-jumper (Tropic Air / Maya Island Air), 20-30 min","water":"bottled / purified only","dengue":"endemic seasonal mosquito-borne risk; repellent advised","malaria":"low/localized rural risk; negligible in tourist zone"},"timing":{"peak":"late-Dec-Apr (dry season; highest rates, biggest crowds)","whale_shark_event_peak":"Apr-May around the full moons (distinct, separate peak); 2026 full moons Mar 14 / Apr 13 / May 12 / Jun 11; windows Mar 12-24, Apr 11-23, May 10-22, Jun 9-21","shoulder_green":"Sep-Nov (green season; better value, hurricane exposure Jun-Nov)","events":"Placencia Lobsterfest ~late June (confirm 2026 date)","booking_window_lead_time":"whale-shark Apr/May 3-4 months; dry-season peak 3-4 months; shoulder 4-6 weeks","fill_the_beds":"green season lead with Monkey River, Cockscomb jaguar preserve, Hopkins Garifuna, reef days, year-round flats fly-fishing","campaign_start_trigger":"whale-shark push fires early-mid Feb 2026; dry-season peak fires late-Sep/Oct 2025; green-season value fires Jun-Jul","fire_date":"2026-02-10"},"jewels":[{"name":"Gladden Spit whale sharks (Apr-May full moons)","si_tag":"Dive Liveaboards","status":"live","tier":"premier","hook":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","bookable_category":"licensed whale-shark dive/snorkel","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"liveaboard","blurb":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","commission":"dive-operator direct — David''s CLIA lane, affiliate -> commissioned-agent 12-18%; reserve fee pass-through"},{"name":"Silk Cayes snorkel / dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","bookable_category":"reef snorkel/dive day","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"diveglobal","blurb":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","commission":"dive-operator direct / affiliate; reserve fee pass-through"},{"name":"Laughing Bird Caye National Park","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","bookable_category":"reef day-trip","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","when":"late-Dec-Apr","commission":"affiliate 4-8% / operator direct; park fee pass-through"},{"name":"Monkey River howler-monkey + manatee watch","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","bookable_category":"guided river/wildlife tour","source":"https://blueturtleplacencia.com/placencia-adventure-tours/monkey-river-tour","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","when":"late-Dec-Apr","commission":"DMC (Barefoot) AOR / affiliate; village fee pass-through"},{"name":"Cockscomb Basin jaguar-preserve day trip","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","bookable_category":"guided day trip","source":"https://en.wikipedia.org/wiki/Cockscomb_Basin_Wildlife_Sanctuary","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate; sanctuary entry pass-through"},{"name":"Garifuna Coast — Hopkins day trip","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Drumming, culture and beaches of the Garifuna village of Hopkins.","bookable_category":"cultural day trip","source":"https://www.hamanasi.com/belize-vacation/cockscomb-jaguar-preserve-tour/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Drumming, culture and beaches of the Garifuna village of Hopkins.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate"},{"name":"Flats fly-fishing (permit / bonefish / tarpon)","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"World-class permit water on the southern flats, year-round.","bookable_category":"guided fly-fishing","source":"https://www.jmbelizetravel.com/placencia-sea-tours/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"World-class permit water on the southern flats, year-round.","when":"late-Dec-Apr","commission":"fishing-lodge/guide direct; affiliate on packaged trips"},{"name":"Placencia sidewalk + fishing village","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","bookable_category":"self-guided","source":"https://chabilmarvillas.com/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","when":"late-Dec-Apr","commission":"none (drives F&B + lodging attach)"}],"faq":[{"q":"Is Placencia good for a honeymoon or wedding?","a":"Yes — it is Belize''s most credible mainland resort/romance market, with real luxury-to-ultra range. Naïa Resort & Spa (39 beach houses + treetop villas on 224 private acres, mile of beach, from ~US$380/night) and SLH-member Itz''ana anchor the beachfront, plus true private-island elopements offshore. The peninsula earns both the wedding and the dive log.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"romance"},{"q":"When can you swim with whale sharks in Placencia?","a":"Around the Mar–Jun full moons at Gladden Spit — the one place on the planet where whale-shark arrival is \"reasonably predictable.\" 2026 full moons are Mar 14, Apr 13, May 12 and Jun 11, with windows ~2 days before to ~10 days after; April and May fill first, so serious divers book three to four months ahead. Encounters are not guaranteed — you''re buying the window.","source":"splashbelize.com, 2026-07-06","si_tag":"liveaboard"},{"q":"What wildlife can you see near Placencia?","a":"Two flagship day trips. The Monkey River eco-tour (a ~45-min coastal boat run then a river cruise) carries you into black-howler-monkey habitat with crocodiles, iguanas, toucans and manatees on the return; and the Cockscomb Basin — the world''s first jaguar preserve, 128,000 acres, est. 1986 — is a half-day inland via Maya Center.","source":"blueturtleplacencia.com, 2026-07-06","si_tag":"expedition"},{"q":"Does Placencia have good beaches and reef?","a":"Yes — the country''s best mainland beaches on a 16-mile peninsula, plus the closest mainland launch to the southern reef. Splash Dive Center''s home waters — the Silk Cayes, South Water Caye and Laughing Bird Caye — are \"postcard perfect islands on the barrier reef\" with turtles, sharks, rays and eels, most a 30–60 minute run out.","source":"splashbelize.com, 2026-07-06","si_tag":"tropical"},{"q":"Can you fly-fish the flats in Placencia?","a":"Yes — the southern flats and river mouths are world-class permit water, fishable year-round for permit, bonefish and tarpon by skiff. It''s a high-value niche booked through Placencia fishing lodges and guides, and a reliable green-season lever when the reef days are between fronts.","source":"jmbelizetravel.com, 2026-07-06","si_tag":"ocean"},{"q":"Is there a destination spa / wellness stay in Placencia?","a":"Yes — Naïa Resort & Spa is built for it: a 224-acre private property with a mile of beach, a destination spa and a private-island couples retreat, strong on both romance and wellness. It''s the anchor for a quiet-beach reset paired with reef or river days.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"wellness"},{"q":"What''s the real risk to plan for in Placencia?","a":"Dive-chamber distance and open-water boat runs, not crime. The nearest recompression chamber is on Ambergris Caye (San Pedro), a meaningful distance north of the southern reef, so plan conservative profiles and no-fly windows; the run to Gladden Spit is ~90 minutes each way with early 6–7am departures. There is no full trauma center on the peninsula — serious cases evacuate to Belize City.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"Is swimming with whale sharks dangerous?","a":"It runs guided-only with a permitted operator — Gladden Spit is inside a marine reserve and only permitted operators may run the aggregation, no-touch and no-chase. Snorkelers work the surface aggregation over 2–3 hours (moderate swimming ability needed); divers descend to ~50–80 ft to meet the sharks and must be certified and guided.","source":"flowersvacationrentals.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Placencia, Belize Travel Guide 2026 — Whale Sharks, Beaches & Reef | TravelWell.World","meta_description":"Plan Placencia: the Gladden Spit whale-shark season (Apr-May full moons), Silk Cayes & Monkey River, best mainland beaches, luxury & private-island resorts, straight L3 safety and dive-chamber facts.","slug":"placencia-belize","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"en","primary_keywords":["Placencia Belize travel guide","whale sharks Placencia","Placencia beaches"],"local_keywords":["tiburon ballena Placencia Belice","temporada tiburon ballena Gladden Spit 2026","playas de Placencia","tour Monkey River Placencia","buceo Silk Cayes Placencia","resorts de lujo Placencia"],"hreflang":["en","es"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Itz''ana Resort & Residences","price_tier":"ultra","virtuoso":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"beachfront + marina, Small Luxury Hotels of the World","source":"https://slh.com/hotels/itz''ana-resort-and-residences"},{"name":"Naia Resort & Spa","price_tier":"luxury","virtuoso":true,"earning":"host-agency / Virtuoso AOR","mor_posture":true,"note":"224-acre, mile of beach, destination spa; R&H + Wellness","source":"https://www.naiaresortandspa.com/"},{"name":"Turtle Inn (Coppola Hideaways)","price_tier":"ultra","virtuoso":true,"earning":"Coppola Hideaways trade / host-Virtuoso / Fora","mor_posture":true,"note":"Balinese-inspired thatched beach hideaway near village","source":"https://thecoppolahideaways.com/resort/turtle-inn"},{"name":"Gladden Private Island","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"single-villa caye, helicopter transfer on 7+ nights, whale sharks off-island","source":"https://www.privateislandsonline.com/central-america/belize/gladden-private-island"},{"name":"Ray Caye Island Resort","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"private island on edge of Gladden Spit & Silk Cayes reserves","source":"https://raycaye.com/"},{"name":"Copal Tree Lodge (Muy''Ono, Toledo)","price_tier":"luxury","virtuoso":false,"earning":"Muy''Ono trade / host-Virtuoso / Fora","mor_posture":true,"note":"rainforest all-inclusive luxury lodge near Punta Gorda","source":"https://etichotels.com/journal/top-10-sustainable-hotels-in-belize/"}],"source_verified":"2026-07-06","hero":{"query":"Placencia, Belize"},"geo":{"lat":16.5155,"lng":-88.3665}}'::jsonb, 80),
  ('playa-del-carmen-mexico', '10S', 'Playa del Carmen', 'Mexico', 'Cenotes, Fifth Avenue and the Cozumel ferry', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","expedition","diveglobal","culture"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":["Quinta Avenida (Fifth Avenue) is a multi-km pedestrian dining/shopping/nightlife street parallel to the beach.","Cozumel reef wall is a 40-minute ferry away (Xcaret Xailing/Winjet/Ultramar, ~US$32 round trip).","Cenotes Chikin-Ha, Chaak Tun and Eden are within ~30 minutes for swim/snorkel/cavern dives.","Xcaret and Xplor eco-parks (14-line, 3.8 km zipline circuit) sit just outside town.","Best weather is November–March; May–October is hot, humid and rainy."],"safety":{"emergency":"911","hospital":"Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200); serious trauma escalates to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","sargassum_window":"Apr-Aug (Jun-Jul peak); Playa moderate risk with barrier program","booking_window_lead_time":"peak 3-4 months; shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"green/sargassum months pivot to cenote dives, Cozumel reef, Xcaret/Xplor parks, Fifth Avenue food+nightlife","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out"},"jewels":[{"name":"Cozumel reef wall (Palancar/Santa Rosa/Columbia)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","bookable_category":"dive excursion / liveaboard","source":"https://www.viator.com/Playa-del-Carmen/Cozumel/day-trips-d5501-d632","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","when":"Dec-Apr","commission":"Amstar excursion 12% or dive-operator affiliate"},{"name":"Cenote cavern dive — Chikin-Ha / Dos Ojos","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","bookable_category":"cenote cavern dive (guide required)","source":"https://www.tripadvisor.com/Attractions-g150812-Activities-Playa_del_Carmen_Yucatan_Peninsula.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","when":"Dec-Apr","commission":"DMC excursion 12% / affiliate 4-8%"},{"name":"Xplor zipline + underground river","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","bookable_category":"eco-park adventure","source":"https://blog.xcaret.com/en/welcome-to-playa-del-carmen-mexico/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","when":"Dec-Apr","commission":"Xcaret Agents / affiliate; park entry pass-through"},{"name":"Cobá + Tulum ruins day loop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","bookable_category":"guided cultural excursion","source":"https://www.amstardmc.com/en/destinations/mexico/tulum/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","when":"year-round","commission":"Amstar 12%; ruin entry pass-through"},{"name":"La Casa de la Playa (Grupo Xcaret)","si_tag":"Romance & Honeymoons","status":"live","tier":"ultra","hook":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","bookable_category":"luxury all-inclusive resort","source":"https://www.travelagentcentral.com/your-business/grupo-xcaret-launches-xcaret-agents-pro-booking-tool","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","when":"Dec-Apr","commission":"Xcaret Agents Pro — 15% auto-paid at check-out"}],"faq":[{"q":"What''s the real risk to plan for in Playa del Carmen?","a":"Sargassum, weather and water — not violent crime against tourists. 2026 is a record-forecast sargassum year, but Playa is moderate risk thanks to active municipal cleanup and a 5-km double-barrier program, with landings in pulses. Drink bottled water, use repellent for dengue (peak May–Nov, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Can I dive Cozumel and the cenotes from Playa del Carmen?","a":"Yes — Playa is the best mainland dive base for both. Cozumel''s drift-wall reef (Palancar, Santa Rosa, Columbia) is a 40-minute ferry away at ~US$32 round trip, and cenote cavern dives sit under 30 minutes inland. Cozumel walls are drift dives for a reputable operator; cenotes are guide-required and weather-independent.","source":"viator.com / tripadvisor.com, 2026-07-04","si_tag":"diveglobal"},{"q":"What is there to do on Fifth Avenue?","a":"Fifth Avenue (Quinta Avenida) is the Riviera Maya''s densest dining and nightlife strip — a multi-kilometre pedestrian street of tacos-to-rooftop bars parallel to the sand. It is the town''s social spine, best on a weekday evening before the crowds; guided food-and-rooftop crawls are the easy way to graze it.","source":"tripadvisor.com, 2026-07-04","si_tag":"entertainment","si_fold_note":"folded from the retired `nightlife` slug into Global Live Entertainment 2026-08-23; the content is kept, the retired slug is not"},{"q":"Are the Xcaret and Xplor parks worth it, especially for families?","a":"Yes — they are the region''s marquee eco-parks. Xcaret runs cenotes, underground rivers and Maya performances; Xplor has Mexico''s largest zipline circuit (14 lines over 3.8 km) plus amphibious buggies. Park admission (~US$85–110 at Xcaret) is pass-through, and both sit just outside town — a full family day out.","source":"blog.xcaret.com, 2026-07-04","si_tag":"expedition"},{"q":"Can I visit Maya ruins from Playa del Carmen?","a":"Yes — it is the corridor''s best ruins base. Tulum''s cliff-top ruins and Cobá''s bikeable jungle pyramids pair in one day loop, and Chichén Itzá is a longer day trip; early morning (Nov/Feb) is best. Amstar and other DMCs run guided excursions, with ruin entry as a pass-through cost.","source":"amstardmc.com, 2026-07-04","si_tag":"culture"},{"q":"Where''s the best luxury for a honeymoon near Playa del Carmen?","a":"The Mayakoba estate and La Casa de la Playa. Mayakoba (Rosewood, Banyan Tree, Andaz) is a gated 595-acre lagoon estate of Virtuoso-affiliated flagships; La Casa de la Playa (Grupo Xcaret) is a 63-suite AAA Five-Diamond boutique ranked #1 Resort in Mexico for 2025. Both are ultra-tier honeymoon addresses on Playa''s doorstep.","source":"jetsetchristina.com / virtuoso.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Playa del Carmen?","a":"November–March is the dry, cooler high season (best weather, highest rates); May–October is hot, humid and rainy at the cheapest rates. The value sweet spots are the May–June and November shoulders at ~30–40% off, with November landing clear of sargassum and ahead of the holiday surge.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Playa del Carmen Travel Guide 2026 — Cenotes, Cozumel Diving & Fifth Avenue | TravelWell.World","meta_description":"Plan Playa del Carmen: cenote diving, the 40-minute Cozumel reef ferry, Fifth Avenue nightlife, Xcaret parks, plus straight 2026 sargassum, Level 2 safety and dive-chamber info.","slug":"playa-del-carmen-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Playa del Carmen","cenotes cerca de Playa del Carmen","ferry a Cozumel desde Playa del Carmen","mejor época para visitar Playa del Carmen 2026","sargazo Playa del Carmen 2026","buceo en cenotes Playa del Carmen","Quinta Avenida Playa del Carmen"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Rosewood Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Andaz / Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Fairmont Mayakoba","price_tier":"luxury","virtuoso":false,"earning":"on application / host AOR","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Playa del Carmen, Mexico"},"geo":{"lat":20.6296,"lng":-87.0739}}'::jsonb, 81),
  ('pucon-chile', '10S', 'Pucón & the Araucanía Lakes, Chile', 'Chile', 'Lake, volcano and araucaria forest', 'live', 'verified', 'mountainValley', 'Lakes, Patagonia & Easter Island', '{"expedition","romance"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"131","emergency_all":{"ambulance_samu":"131","fire":"132","police_carabineros":"133"},"advisory_level":"L2","advisory_source":"US State Dept, reissued 2026-05-20; verified 2026-07-07","book_enabled":true,"bin":"freely bookable (L2)","regional_note":"La Araucanía/Arauco/Biobío state-of-emergency active (rural forestry/land-conflict corridors + Ruta-5); attacks target forestry corporations/landowners; advisory does NOT name Pucón, Villarrica, or the Lake District; tourist lake-zone historically safe/open — disclose as context.","air_access_verified":{"airport":"ZCO — Temuco / La Araucanía Intl","to_santiago":"~1 hr 25 min flight to SCL (LATAM / Sky / JetSmart nonstop)","airport_to_pucon":"~100 km / ~1 hr 15 min drive"},"trauma_evac":"Regional care Villarrica/Temuco (Hospital Hernán Henríquez Aravena); serious trauma stabilize then air-evac to Santiago via ZCO→SCL","water_potable":true,"volcano":{"name":"Villarrica","status":"ACTIVE — open-vent persistent lava lake","technical_alert":"Green (verde)","alert_as_of":"2026-06-07 (SERNAGEOMIN/SENAPRED)","last_significant_eruption":"Feb 2023","climb_rule":"guided-only; suspends without notice if alert rises above Yellow; re-check SERNAGEOMIN/RNVV/SENAPRED/ONEMI day-of","monitor_sources":["SERNAGEOMIN / RNVV","SENAPRED","ONEMI"]},"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-08-19","page_updated":"2026-08-18T23:18:12+01:00"}},"timing":{"peak":["Dec","Jan","Feb"],"ski_peak":["Jun","Jul","Aug","Sep"],"shoulder":["Oct","Nov","Mar"],"off_season_fill":["Apr","May","Sep"],"inflection":"late Nov ramp (summer); late May–Jun ramp (ski)","fire_date":"early-mid Nov for summer peak; mid-May for ski peak (curve-start minus 1–2 weeks)"},"jewels":[{"name":"Villarrica volcano summit + crater glow","si_tag":"expedition","tier":"comfort","source":"https://www.nomades.com/en/pucon/villarrica-volcano-climb-id190","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The signature. Rope up before dawn in summer, top out at ~2,847 m, look into a live vent","si":"expedition","blurb":"The signature. Rope up before dawn in summer, top out at ~2,847 m, look into a live vent","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"guided-climb operator package (~130k–150k CLP pp)"},{"name":"Trancura whitewater rafting (III / IV–V)","si_tag":"expedition","tier":"comfort","source":"https://www.elementos-chile.com/en/tour/adventure-tourism/rafting-upper-trancura-class-iv","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Family Bajo or committing Alto, safety-kayakers on the seams, ~3 hr","si":"expedition","blurb":"Family Bajo or committing Alto, safety-kayakers on the seams, ~3 hr","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"rafting operator package + activity affiliate"},{"name":"Huerquehue NP — araucaria groves + Los Lagos","si_tag":"expedition","tier":"essential","source":"https://www.travelaid.cl/eng/excursions/hikes/loslagos.htm","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Cathedral monkey-puzzle forest over a string of glass-clear lakes; ~13 km, a full day","si":"expedition","blurb":"Cathedral monkey-puzzle forest over a string of glass-clear lakes; ~13 km, a full day","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"guided-trek/transfer commissionable; CONAF entrance non-commissionable"},{"name":"Winter ski on Villarrica flanks","si_tag":"expedition","tier":"comfort","source":"https://mychiletravelguide.com/pucon/","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"ski package + lift/rental affiliate + cabaña MoR"},{"name":"Termas Geométricas designer hot springs","si_tag":"WSR","tier":"comfort","source":"https://www.interpatagonia.com/conaripe/termas-geometricas_i.html","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"WSR","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"transfer/tour commissionable; gate fee non-commissionable"},{"name":"Thermal circuit — Los Pozones/Menetúe/Huife","si_tag":"WSR","tier":"essential","source":"https://mychiletravelguide.com/pucon/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"A string of alternative hot springs — the wellness-overlay depth beyond the marquee","si":"WSR","blurb":"A string of alternative hot springs — the wellness-overlay depth beyond the marquee","when":"year-round","commission":"thermal-lodge stay + transfer"},{"name":"Villarrica lake beach + sunset","si_tag":"romance","tier":"essential","source":"https://www.visitchile.com/en/tourist-guides/pucon-and-villarrica/","hook":"Black-sand volcanic beaches on Lake Villarrica; kayak, SUP, and the golden-hour volcano silhouette — the romance set-piece","si":"romance","blurb":"Black-sand volcanic beaches on Lake Villarrica; kayak, SUP, and the golden-hour volcano silhouette — the romance set-piece","commission":"lakeshore-lodge/villa MoR + watersport affiliate"},{"name":"Mapuche ruka + cuisine experience","si_tag":"CLT","tier":"essential","source":"https://www.elementos-chile.com/en/tour/cultours/cultour-mapuche-ruka","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Hosted by Araucanía families — enter the ruka, hear the cosmology and the meaning of the flag and spiritual structure","si":"culture","blurb":"Hosted by Araucanía families — enter the ruka, hear the cosmology and the meaning of the flag and spiritual structure","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"cultural-tour operator package (Elementos/Zenit)"},{"name":"Ojos del Caburgua turquoise pools + falls","si_tag":"expedition","tier":"essential","source":"https://www.visitchile.com/en/ojos-del-caburgua/","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"half-day tour/transfer commissionable; site free/low-fee"}],"faq":null,"seo":{"meta_title":"Pucón, Chile Travel Guide — Villarrica Volcano, Hot Springs & Lake District Adventure | TravelWell","search_language":"es-CL","local_keywords":["qué hacer en Pucón","volcán Villarrica ascenso","Termas Geométricas","Parque Nacional Huerquehue","rafting río Trancura","termas cerca de Pucón","Ojos del Caburgua","experiencia mapuche ruka","cuándo ir a Pucón","Pucón es seguro"],"hreflang":["en","es-CL"],"jsonld_type":"TouristDestination","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Hotel Antumalal","tier":"ULTRA/icon","earning":"consortia-commissionable (Virtuoso/Fora potential) + direct","note":"1950 Bauhaus icon on Lake Villarrica; 16 rooms + 3 chalets + Lake House; Pollak family-owned"},{"name":"andBeyond Vira Vira","tier":"ULTRA","earning":"andBeyond/consortia-commissionable + all-in MoR potential","note":"55-acre organic hacienda on the Liucura River; 6 lodge suites + 12 villa suites; guided-adventure inclusive"},{"name":"AWA / Puerto Varas ultra corridor (cross-ref)","tier":"ULTRA (cross-ref)","earning":"consortia + multi-property MoR","note":"two-lake/two-volcano ultra string pairing Pucón with Puerto Varas/Llanquihue"}],"source_verified":null,"hero":{"query":"Pucón & the Araucanía Lakes, Chile, Chile"},"geo":{"lat":-39.282,"lng":-71.955}}'::jsonb, 82),
  ('puerto-aventuras-mexico', '10S', 'Puerto Aventuras', 'Mexico', 'Gated marina, reef off the beach', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","diveglobal","ocean","wildlife"}', '{}', '{"comfort","premier"}', null, null, '{"key_facts":["One of the few mainland deep-water marinas between Cancún and Belize City — a safe-haven harbor.","The reef sits ~100 feet from shore, allowing several dives per day with minimal transit.","Gated community with controlled access and 24/7 security — among the safest areas in the Riviera Maya.","Adjacent Dolphin Discovery offers swims with dolphins, sea lions and manatees.","Cenote Azul (between Puerto Aventuras and Playa del Carmen) makes it an easy cenote-dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~20 km north; local clinics stabilize/transfer; major trauma to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest; marina monitors weather)","marina_sportfishing_calendar":"charters year-round weather-permitting; peak billfish/dorado spring dry window (Mar-Jun sailfish/mahi); confirm species per season with operator","sargassum_window":"Apr-Aug (Jun-Jul peak); marina/inlet + dive focus softens beach dependence","booking_window_lead_time":"peak 3-4 months (gated villa/condo stock finite, book earlier); shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"sargassum/green months lead with near-shore reef dives, Cenote Azul, Dolphin Discovery, sportfishing charters, marina promenade","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; spring-sportfishing / dive-base push through sargassum months"},"jewels":[{"name":"Deep-water marina sportfishing charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","bookable_category":"fishing charter","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","when":"Dec-Apr","commission":"affiliate 4-8% / DMC 12%; berth fees pass-through"},{"name":"Dolphin Discovery swim","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","bookable_category":"marine wildlife experience","source":"https://www.dolphindiscovery.com/riviera-maya/riviera-maya.asp","si":"wildlife","blurb":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","commission":"brand affiliate; park entry pass-through"},{"name":"Shore-adjacent reef dive (reef ~100 ft out)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Near-shore reef dives with minimal transit — several dives in a day.","bookable_category":"reef dive","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Near-shore reef dives with minimal transit — several dives in a day.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%"},{"name":"Cenote Azul cavern dive/snorkel","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","bookable_category":"cenote cavern dive (guide required)","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"diveglobal","blurb":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","commission":"DMC 12% / affiliate 4-8%; entry pass-through"},{"name":"Dreams Aventuras Riviera Maya","si_tag":"Romance & Honeymoons","status":"live","tier":"premier","hook":"Secure, calm gated-community all-inclusive honeymoon base.","bookable_category":"all-inclusive resort","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Secure, calm gated-community all-inclusive honeymoon base.","when":"Dec-Apr","commission":"all-inclusive AOR ~12%"}],"faq":[{"q":"What''s the real risk to plan for in Puerto Aventuras?","a":"Water, mosquitoes, hurricanes and sargassum — not crime. Drink bottled/purified water, use repellent for dengue (peak May–November, no malaria in tourist Quintana Roo), and note hurricane season runs June–November. Sargassum is heavy region-wide in 2026 (Apr–Aug), but the marina and dive focus soften the beach hit here.","source":"cdc.gov / deeparrival.com, 2026-07-04","si_tag":"safety"},{"q":"What is the marina and sportfishing like in Puerto Aventuras?","a":"It is one of the few mainland deep-water marinas between Cancún and Belize City — a secure safe-haven harbor for yachts, sailors and sportfishers. Offshore charters run year-round (weather permitting), with the peak billfish and mahi window in the Mar–Jun spring dry season; berth fees are pass-through and the guided charter is the commissionable wrapper.","source":"alohawanderers.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Puerto Aventuras a good dive base?","a":"Yes — it is a genuine near-shore reef and cenote base. The reef is only ~100 feet from the beach, so you can log several dives a day with minimal boat transit, and Cenote Azul (between Puerto Aventuras and Playa del Carmen) puts cave country within easy reach. Best reef visibility runs Nov–May.","source":"prodiveinternational.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Puerto Aventuras good for families?","a":"Very — it is built for calm, safe family days. The adjacent Dolphin Discovery center offers sea-inlet swims with bottlenose dolphins, sea lions and manatees; add the gated 24/7-security layout, a calm marina promenade and near-shore reef, and it suits families and multigenerational groups well.","source":"dolphindiscovery.com, 2026-07-04","si_tag":"family"},{"q":"Is Puerto Aventuras good for a honeymoon?","a":"Yes, for couples who want secure and quiet over party energy. The in-community options are the branded all-inclusive Dreams Aventuras and private gated marina/golf villas with chef and concierge; the wider luxury tier runs ~US$400–600+/night in March. For branded ultra, Mayakoba (Rosewood, Banyan Tree) is ~30–40 min north with an easy marina/dive day trip.","source":"machupicchu.org / trivago.com, 2026-07-04","si_tag":"romance"},{"q":"Can I do Maya ruins from Puerto Aventuras?","a":"Yes — Tulum and Cobá are easy guided day trips, alongside Akumal''s turtle bay ~10 min south. Amstar and other Riviera Maya DMCs run cenote, Tulum-ruins and Akumal-turtle excursions from Puerto Aventuras; entries are pass-through, with the guided excursion the commissionable wrapper.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"},{"q":"When is the best time to visit Puerto Aventuras?","a":"December–April is peak (best weather, highest rates); the value windows are the May–June and November shoulders at ~30–40% off, with November clear of sargassum. The green season (Jun–mid-Oct) is hot, rainy and cheapest with hurricane exposure — but the marina and dive product hold up better than a pure beach stay.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Puerto Aventuras Travel Guide 2026 — Marina, Reef Diving & Dolphins | TravelWell.World","meta_description":"Plan Puerto Aventuras: a gated deep-water marina town with reef 100 ft from shore, cenote diving, dolphin swims and sportfishing, plus 2026 sargassum, Level 2 safety and dive-chamber info.","slug":"puerto-aventuras-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Puerto Aventuras","marina Puerto Aventuras","buceo en Puerto Aventuras","Dolphin Discovery Puerto Aventuras","pesca deportiva Puerto Aventuras","villas en Puerto Aventuras","Cenote Azul Puerto Aventuras","es seguro Puerto Aventuras"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Private gated marina/golf villas","price_tier":"luxury","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"top of in-community ladder; no true ultra hotel in-community","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/puerto-aventuras"},{"name":"Dreams Aventuras Riviera Maya","price_tier":"premier","virtuoso":false,"earning":"all-inclusive AOR ~12% (Hyatt Inclusive/host)","mor_posture":true,"note":"top hotel SKU in-community, not true ultra","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras"},{"name":"Rosewood Mayakoba (~30-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Aventuras, Mexico"},"geo":{"lat":20.4986,"lng":-87.2261}}'::jsonb, 83),
  ('puerto-morelos-mexico', '10S', 'Puerto Morelos', 'Mexico', 'A reef 500 meters off a sleepy fishing dock', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","adventure","culinary"}', '{}', '{"essential","comfort","premier"}', null, 'core', '{"key_facts":["Puerto Morelos Reef National Park lies less than 500 m offshore, one of the best-preserved in the Caribbean","Juan Escutia boat is now an artificial reef; reef holds turtles, rays, nurse/bull sharks","Northern gateway to the ~17 km Route of the Cenotes (entry ~150-250 MXN each)","Deep-sea fishing for dorado, wahoo, tuna, barracuda","Runs ~20-30% cheaper than Playa del Carmen, 40-60% cheaper than Cancún Hotel Zone"],"safety":{"emergency":"911","hospital":"town clinics; major trauma in Cancún (~36 km, Galenia/Hospiten - verify) or Playa del Carmen; hyperbaric via SSS Cancún / Cozumel","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry/high season; driest reef water, own rates peak)","shoulder":"May-Jun & Nov (~30-40% off winter, layered on structural ~20-30% vs Playa del Carmen)","green":"Jun-mid-Oct (hurricane season, ~40-60% off; reef/cenote year-round, dry-season visibility best)","booking_lead":"shoulder/green beds 2-4 wks; reef/cenote tours 1-3 wks; Dec-Apr beds + Zoëtry/Royalton Reserve ultra suite 3-6+ months (more for Christmas/NY)","off_season_specials":"double-discount play - ''cheaper than Cancún AND low season''; pair value bed with year-round national-park reef + weather-resilient Route of the Cenotes; disclose hurricane/sargassum","event_peaks":"Christmas-New Year, US spring break (Mar); no single marquee wildlife event - reef + cenotes are the year-round draw","campaign_start":"winter/value-vs-Cancún Aug-Sep; green-season ''cheaper base + cenotes'' Apr-May; ultra corridor (Mayakoba/Zoëtry) 6-9 months ahead"},"jewels":[{"name":"Juan Escutia wreck","si_tag":"diveglobal","status":"future","tier":"comfort","hook":"sunken boat now an artificial reef and fish refuge","bookable_category":"guided reef/wreck dive","source":"https://www.kooxdiving.com/en/activities/diving-in-the-sea/puerto-morelos-reef-shipwreck-diving/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"sunken boat now an artificial reef and fish refuge","when":"Dec-Apr","commission":"local dive-op → OTA affiliate"},{"name":"Puerto Morelos Reef National Park snorkel","si_tag":"ocean","status":"future","tier":"essential","hook":"living reef under 500 m offshore, turtles/rays/lobster","bookable_category":"guided reef snorkel/dive","source":"https://voyage-mexico.com/en/puerto-morelos.html","si":"ocean","blurb":"living reef under 500 m offshore, turtles/rays/lobster","commission":"local operator → OTA (park fee pass-through)"},{"name":"Deep-sea fishing charter","si_tag":"ocean","status":"future","tier":"premier","hook":"half/full-day for dorado, wahoo, tuna, barracuda","bookable_category":"private/shared charter","source":"https://voyage-mexico.com/en/puerto-morelos.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"half/full-day for dorado, wahoo, tuna, barracuda","when":"Dec-Apr","commission":"local charter operator → curated-recommend"},{"name":"Route of the Cenotes","si_tag":"globaladv","status":"future","tier":"comfort","hook":"~17 km jungle road of open/semi-open/cave cenotes","bookable_category":"day tour + per-cenote entry","source":"https://snorkelingadventure.com/blog/snorkeling-puerto-morelos-cenotes-riviera-maya-adventure/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"~17 km jungle road of open/semi-open/cave cenotes","when":"Dec-Apr","commission":"DMC/local operator → OTA (entry pass-through)"},{"name":"Fishing-village seafood + craft market","si_tag":"culinary","status":"future","tier":"essential","hook":"fresh-off-the-boat ceviche + plaza craft market","bookable_category":"food/culture experience","source":"https://www.palladiumhotelgroup.com/en/travel-guides/mexico/riviera-maya/what-to-see/puerto-morelos","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"fresh-off-the-boat ceviche + plaza craft market","when":"Dec-Apr","commission":"curated-recommend (largely non-commissionable)"}],"faq":[{"q":"What''s the real risk to plan for in Puerto Morelos?","a":"Sargassum, hurricanes and water — not crime. 2026 is heavy region-wide for sargassum, and Puerto Morelos'' open Caribbean-facing beaches are affected, so plan cenote and reef days as hedges; drink bottled water, use repellent for dengue (no malaria in the tourist zone), and note hurricane season runs June–November, September riskiest.","source":"howisthesargassum.com","si_tag":"safety"},{"q":"Is Puerto Morelos good for diving and the Juan Escutia wreck?","a":"Yes — it is an underrated day-boat dive base. The Puerto Morelos Reef National Park sits under 500 m offshore, one of the Caribbean''s best-preserved reefs, and the sunken Juan Escutia is now an artificial reef and fish refuge steps away. Visibility is best in the dry Oct–March window; book in town, where it is cheaper and supports local operators.","source":"voyage-mexico.com","si_tag":"diveglobal"},{"q":"Can I go deep-sea fishing from Puerto Morelos?","a":"Yes — it is a working fishing port, so charters are authentic and close at hand. Half- and full-day trips target dorado (mahi-mahi), wahoo, tuna and barracuda, with gear and guide included; the species mix is seasonal, so confirm with the operator. It pairs naturally with the fresh-off-the-boat ceviche at the beachfront cantinas.","source":"voyage-mexico.com","si_tag":"ocean"},{"q":"What is the Route of the Cenotes?","a":"A ~17 km jungle road of cenotes running inland from town — Puerto Morelos is its northern gateway. It strings together open, semi-open and cave cenotes for swimming, cavern diving and ziplining, at roughly 150–250 MXN entry each. Because they are shaded jungle sites, cenotes are weather-resilient — a strong rainy-day and green-season option.","source":"snorkelingadventure.com","si_tag":"globaladv"}],"seo":{"meta_title":"Puerto Morelos, Mexico: Reef, Cenotes & Fishing Village","meta_description":"A quiet Riviera Maya port with a national-park reef 500 m offshore, the Juan Escutia wreck, and the Route of the Cenotes. Cheaper than Cancún — when and how to book.","slug":"puerto-morelos-mexico","primary_keyword":"Puerto Morelos reef diving","long_tail":["Puerto Morelos Reef National Park","Juan Escutia wreck dive","Route of the Cenotes Puerto Morelos","Puerto Morelos fishing village","Puerto Morelos vs Cancun value"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["arrecife Puerto Morelos","Parque Nacional Arrecife de Puerto Morelos","buceo pecio Juan Escutia","Ruta de los Cenotes","pueblo pesquero Puerto Morelos","villas frente al mar Puerto Morelos","qué hacer en Puerto Morelos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"note":"Quintana Roo/Mexico US L2 (Exercise Increased Caution) - freely bookable; MXN currency, USD widely accepted"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"culinary","name":"culinary","status":"future"}],"ultra":[{"name":"Zoëtry / Royalton Reserve Paraíso de la Bonita, a Luxury Collection Resort, Riviera Maya","why_ultra":"IN Puerto Morelos (Hwy Km 328); 90-100 ocean-front suites w/ plunge pools, 14 acres, thalasso spa, one of only 3 Luxury Collection all-inclusives worldwide, AAA Five Diamond 15 yrs (Zoëtry heritage); rebranded to Royalton Reserve adults-only, operating 2026 - verify current brand","earning":"on application / via host-Virtuoso (Marriott Luxury Collection + Royalton/Blue Diamond); verify %","virtuoso_value_add":"verify Marriott STARS/Luxury Collection amenities - not documented","mor":"commission-on-net; no net-rate resale markup","source":"https://www.tripadvisor.com/Hotel_Review-g240327-d28213141-Reviews-Royalton_Reserve_Paraiso_de_la_Bonita_a_Luxury_Collection_Resort_Riviera_Maya_Adult_A.html"},{"name":"Mayakoba enclave (Rosewood / Banyan Tree / Fairmont / Andaz) - ADJACENT, verify municipality","why_ultra":"620-acre gated ultra enclave, 4 flagship resorts; STRAIGHT GEOGRAPHY: administratively in Solidaridad (Km 298, Playa del Carmen area), NOT Puerto Morelos - do not label as in Puerto Morelos; nearest true-ultra cluster + standard corridor pull-out","earning":"on application / via host-Virtuoso (Rosewood Elite / Fairmont / Hyatt Prive / Banyan Tree); verify %","virtuoso_value_add":"Rosewood Mayakoba is Virtuoso-preferred - verify current amenity package","mor":"commission-on-net; no resale markup","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Morelos, Mexico"},"geo":{"lat":20.8478,"lng":-86.8758}}'::jsonb, 84),
